xof_kt(Type, Input, OutputLength) ->
    libdecaf_nif:xof_kt(Type, Input, OutputLength).

-doc """
Compute KangarooTwelve in one call and return output bytes.

Customization accepts iodata and defaults to empty. It is stored during initialization and appended after
the message per RFC 9861. Hash defaults are 32 bytes for KT128 and 64 for KT256.

Lengths are in bytes; states are immutable and must be replaced with each returned state.

```erlang
Output = libdecaf:xof_kt(kt128, <<"invoice-42">>, 16, <<"orders/v1">>),
16 = byte_size(Output).
```
""".
-doc #{group => <<"XOF API">>}.
-spec xof_kt(Type, Input, OutputLength, CustomizationString) -> Output when
    Type :: kt128 | kt256,
    Input :: iodata(),
    OutputLength :: non_neg_integer(),
    CustomizationString :: iodata(),
    Output :: binary().
xof_kt(Type, Input, OutputLength, CustomizationString) ->
    libdecaf_nif:xof_kt(Type, Input, OutputLength, CustomizationString).

-doc """
Compute ParallelHash in one call and return output bytes.

`BlockSize` is a positive byte count and affects the result: it must match the protocol or other
implementation. Input is processed in constant memory regardless of block size. Update boundaries do not
define blocks. Customization defaults to empty. ParallelHash binds the output length; ParallelHashXOF
produces a distinct extensible stream. The implementation processes blocks serially.

Lengths are in bytes; states are immutable and must be replaced with each returned state.

```erlang
Output = libdecaf:xof_parallelhash(parallelhashxof128, <<"invoice-42">>, 16, 8),
16 = byte_size(Output).
```
""".
-doc #{group => <<"XOF API">>}.
-spec xof_parallelhash(Type, Input, OutputLength, BlockSize) -> Output when
    Type :: parallelhashxof128 | parallelhashxof256,
    Input :: iodata(),
    OutputLength :: non_neg_integer(),
    BlockSize :: pos_integer(),
    Output :: binary().
xof_parallelhash(Type, Input, OutputLength, BlockSize) ->
    libdecaf_nif:xof_parallelhash(Type, Input, OutputLength, BlockSize).

